 static int checks,failures;
 static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static void Check(string n,bool v){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 static void Simulate(Window pet,double seconds){double start=(double)Get(pet,"footballKickStart");for(int i=0;i<=seconds*120;i++)Call(pet,"TickFootball",start+i/120.0,1.0/120);}
 static Button Find(DependencyObject root,string text){var b=root as Button;if(b!=null&&Convert.ToString(b.Content)==text)return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find(VisualTreeHelper.GetChild(root,i),text);if(found!=null)return found;}return null;}
 static ComboBox FindCombo(DependencyObject root){var c=root as ComboBox;if(c!=null&&System.Windows.Automation.AutomationProperties.GetName(c)=="足球表演轮数")return c;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=FindCombo(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
 static void Click(Window terminal,string text){var b=Find(terminal,text);if(b==null){var demo=Find(terminal,"动作演示与足球 →");if(demo!=null){demo.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));terminal.UpdateLayout();b=Find(terminal,text);}}if(b==null)throw new Exception("Missing button: "+text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
