 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var messages=(BubbleQueue)Get(pet,"messages");messages.Clear();Call(pet,"OpenTerminal");var terminal=(TerminalWindow)Get(pet,"terminal");terminal.ShowPage("动作与移动");terminal.UpdateLayout();var ball=(FootballWorld)Get(pet,"football");
 terminal.WindowStyle=WindowStyle.None;terminal.ResizeMode=ResizeMode.NoResize;terminal.WindowState=WindowState.Maximized;terminal.Topmost=true;terminal.Activate();SetForegroundWindow(new WindowInteropHelper(terminal).Handle);Pump();terminal.Topmost=false;if(GetForegroundWindow()==new WindowInteropHelper(terminal).Handle){Check("test console is foreground",true);Check("own full screen console does not suppress preview",!DesktopActions.FullScreenForeground());}else Console.WriteLine("SKIP foreground checks: Windows refused foreground focus for the test process");
 Set(pet,"assistantSnapshot",new AssistantSnapshot{CodexRow=7});Click(terminal,"原地颠足球");double now=((Stopwatch)Get(pet,"clock")).Elapsed.TotalSeconds;Call(pet,"TickFootball",now,.016);Check("console juggle survives existing Codex work",ball.Active&&(string)Get(pet,"footballMode")=="juggle");
 var sprites=(SpriteActions)Get(pet,"signature");Check("console juggle displays approved strip",Object.ReferenceEquals(((SpriteView)Get(pet,"sprite")).Frame,sprites.Frame("juggle",.00125)));
 Set(pet,"assistantSnapshot",null);messages.Add(new BubbleMessage{Key="test:existing",Text="existing notice",Notification=true},now);Click(terminal,"原地颠足球");Call(pet,"TickFootball",now,.016);Check("manual preview survives an existing notice",ball.Active);Check("existing notification is preserved",messages.Current!=null&&messages.Current.Notification);
 messages.Add(new BubbleMessage{Key="test:existing",Text="new notice",Notification=true},now);Call(pet,"TickFootball",now,.016);Check("new notification still preempts manual play and retains prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");messages.Clear();
 Click(terminal,"凌空抽射 · 演示");Check("equipment button uses interactive volley",ball.Active&&(string)Get(pet,"footballMode")=="volley");
