 pet.Hide();Click(terminal,"原地颠足球");Check("manual preview restores hidden actor",pet.IsVisible&&ball.Active);Click(terminal,"收起足球");Check("console stop hides ball",!ball.Active&&!((Window)Get(pet,"footballWindow")).IsVisible);
 Set(pet,"assistantSnapshot",new AssistantSnapshot{CodexRow=7});Call(pet,"StartFootball","idle-juggle");Call(pet,"TickFootball",now,.016);Check("autonomous play still yields to work and retains prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");Set(pet,"assistantSnapshot",null);
 Click(terminal,"向上挑球");Check("console upward flick uses new action",ball.Active&&(string)Get(pet,"footballMode")=="flick");Click(terminal,"倒挂金钩");Check("console bicycle uses new action",ball.Active&&(string)Get(pet,"footballMode")=="bicycle");
 Click(terminal,"抛球 · 追球抽射");Check("console toss starts upward flick",ball.Active&&(string)Get(pet,"footballMode")=="flick");Call(pet,"NotifyWorkEnd",new SkillAlert{Count=15,Key="work-end:test",Text="距离下班还有15分钟",Row=3});Check("real reminder interrupts manual game and retains prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");
 messages.Clear();Set(pet,"footballRepeatCount",1);Click(terminal,"原地颠足球");double deadline=(double)Get(pet,"footballUntil");Check("manual juggle has finite duration",!Double.IsInfinity(deadline));Call(pet,"TickFootball",deadline+.01,.016);Check("juggle exits automatically and retains prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");
 Set(pet,"footballRepeatCount",3);Click(terminal,"原地颠足球");Check("three selected rounds have bounded duration",Math.Abs((double)Get(pet,"footballUntil")-(double)Get(pet,"footballStart")-19.2)<.001);Call(pet,"StopFootball");
 Set(pet,"footballRepeatCount",1);Click(terminal,"凌空抽射 · 演示");double kickStart=(double)Get(pet,"footballKickStart");Simulate(pet,2.2);Set(pet,"footballRebounded",true);Set(pet,"footballReboundAt",kickStart+2.2);Call(pet,"TickFootball",kickStart+2.9,.016);Check("single volley stops after landing and rebound and retains prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");
 Set(pet,"footballRepeatCount",2);Click(terminal,"凌空抽射 · 演示");kickStart=(double)Get(pet,"footballKickStart");Simulate(pet,2.2);Set(pet,"footballRebounded",true);Set(pet,"footballReboundAt",kickStart+2.2);Call(pet,"TickFootball",kickStart+2.9,.016);Check("two rounds allow another chase",ball.Active&&(int)Get(pet,"footballShotsLeft")==1);Call(pet,"StopFootball");
 terminal.ShowPage("动作与移动");terminal.UpdateLayout();Click(terminal,"四角巡逻");Click(terminal,"挥手");terminal.ShowPage("动作与移动");terminal.UpdateLayout();Check("movement selection remains highlighted after action click",System.Windows.Automation.AutomationProperties.GetItemStatus(Find(terminal,"四角巡逻"))=="已选中"&&Find(terminal,"四角巡逻").Effect!=null&&System.Windows.Automation.AutomationProperties.GetItemStatus(Find(terminal,"全屏二维漫游"))=="未选中");
 Click(terminal,"大");Click(terminal,"挥手");terminal.ShowPage("动作与移动");terminal.UpdateLayout();Check("size selection remains highlighted after focus leaves",Find(terminal,"大").Effect!=null&&System.Windows.Automation.AutomationProperties.GetItemStatus(Find(terminal,"标准"))=="未选中");
 var tray=(System.Windows.Forms.NotifyIcon)Get(pet,"tray");System.Windows.Forms.ToolStripMenuItem actionMenu=null;foreach(System.Windows.Forms.ToolStripItem item in tray.ContextMenuStrip.Items)if(item.Text=="动作选择")actionMenu=(System.Windows.Forms.ToolStripMenuItem)item;Check("right click menu exposes action selector",actionMenu!=null&&actionMenu.DropDownItems.Count>=18);foreach(System.Windows.Forms.ToolStripItem item in actionMenu.DropDownItems)if(item.Text=="颠足球 · 限次表演")((System.Windows.Forms.ToolStripMenuItem)item).PerformClick();Check("right click starts same bounded football action",ball.Active&&(string)Get(pet,"footballMode")=="juggle"&&!Double.IsInfinity((double)Get(pet,"footballUntil")));foreach(System.Windows.Forms.ToolStripItem item in actionMenu.DropDownItems)if(item.Text=="停止当前表演")((System.Windows.Forms.ToolStripMenuItem)item).PerformClick();Check("right click stop ends current performance",!ball.Active);
 foreach(System.Windows.Forms.ToolStripItem item in actionMenu.DropDownItems)if(item.Text=="放大镜寻找 · 一次")((System.Windows.Forms.ToolStripMenuItem)item).PerformClick();Check("right click search uses separate search atlas",(string)Get(pet,"signatureAction")=="search");
 foreach(System.Windows.Forms.ToolStripItem item in actionMenu.DropDownItems)if(item.Text=="打个盹 · 一次")((System.Windows.Forms.ToolStripMenuItem)item).PerformClick();Check("right click sleep uses separate sleep atlas",(string)Get(pet,"signatureAction")=="sleep");
 var mode=(System.Collections.Generic.Dictionary<string,Button>)Get(terminal,"movementButtons");Check("only one movement option is selected",System.Linq.Enumerable.Count(mode.Values,b=>System.Windows.Automation.AutomationProperties.GetItemStatus(b)=="已选中")==1);
 terminal.ShowPage("动作演示");terminal.UpdateLayout();var rounds=FindCombo(terminal);rounds.SelectedIndex=2;Check("round selector updates shared pet setting",(int)Get(pet,"footballRepeatCount")==3);Check("round setting persists",System.IO.File.ReadAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings.ini")).Contains("footballRepeats=3"));
 terminal.UpdateLayout();var panel=(FrameworkElement)terminal.Content;var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)panel.ActualWidth,(int)panel.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(panel);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var f=System.IO.File.Create(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"actions-status-ui.png")))encoder.Save(f);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
